package be.winnetrie.mod.simpleserverutilities.network;
import be.winnetrie.mod.simpleserverutilities.SimpleServerUtilities;import net.minecraft.network.RegistryFriendlyByteBuf;import net.minecraft.network.codec.StreamCodec;import net.minecraft.network.protocol.common.custom.CustomPacketPayload;import net.minecraft.resources.ResourceLocation;
public record KitRequestPayload(boolean admin,String selectedId,long requestId) implements CustomPacketPayload{public static final Type<KitRequestPayload> TYPE=new Type<>(ResourceLocation.fromNamespaceAndPath(SimpleServerUtilities.MODID,"kit_request"));public static final StreamCodec<RegistryFriendlyByteBuf,KitRequestPayload> STREAM_CODEC=StreamCodec.of((b,p)->{b.writeBoolean(p.admin);b.writeUtf(p.selectedId,64);b.writeVarLong(p.requestId);},b->new KitRequestPayload(b.readBoolean(),b.readUtf(64),b.readVarLong()));public KitRequestPayload{selectedId=PayloadBounds.string(selectedId,64);requestId=Math.max(0L,requestId);}@Override public Type<? extends CustomPacketPayload> type(){return TYPE;}}
